  ('e80f31e5-dc66-59bf-89a7-3aa5075e161c', null, (select id from public.skills where slug = 'read-g10-character-setting-plot'), null, 'hard',
   $q$How does Noor's development over the story help express its theme?$q$, $q$[{"text":"She moves from enjoying the project to resenting it, suggesting that service hours are a poor way to teach students.","is_correct":false,"misconception_token":"misreads-character-change"},{"text":"She moves from careless work to perfect work, suggesting that mistakes in history projects can never be fixed later.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"She moves from valuing speed to valuing the people behind the numbers, suggesting that records hold human stories hurried work misses.","is_correct":true},{"text":"She moves from trusting adults to doubting them, suggesting that older people should not be put in charge of young volunteers.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$She moves from valuing speed to valuing the people behind the numbers, suggesting that records hold human stories hurried work misses.$q$, $q$She ends by staying late "which earned her nothing extra" and offering to record margin notes, showing she now cares about stories like Ruth's. She does not come to resent the work; she volunteers for more of it.$q$, 'draft', 'ad335b15-aa6a-592a-96df-74695b05d564')
