  ('f8910320-5799-56bf-a4ae-b860a240715a', null, (select id from public.skills where slug = 'read-g10-character-setting-plot'), null, 'medium',
   $q$Why does the heron first refuse the kingfisher's offer?$q$, $q$[{"text":"It does not believe that a deep pool exists past the fallen willow.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Following the kingfisher would mean admitting that stillness was not enough.","is_correct":true},{"text":"It is too weak from hunger to fly as far as the upstream pool.","is_correct":false,"misconception_token":"misreads-sequence"},{"text":"It has promised the other herons that it will guard the shrinking pond.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Following the kingfisher would mean admitting that stillness was not enough.$q$, $q$The narrator explains, "To follow a bird who could not keep still would be to admit that stillness was not enough." Its weakness grows only during the next three days, and it still makes the flight.$q$, 'draft', '70a8f531-992f-5c7d-9e65-b26e8767e4a4')
