values
  ('0a57d934-ea4f-5e99-8206-0b00c4386eae', null, (select id from public.skills where slug = 'read-g10-character-setting-plot'), null, 'hard',
   $q$In the last stanza the uncle "very carefully, did not touch the pencil" and "only signed his name beneath mine." What does this ending reveal about how he has changed?$q$, $q$[{"text":"He accepts a map that shows the change without erasing his memory, and he treats the speaker as a fellow mapmaker.","is_correct":true},{"text":"He decides that memories do not belong on maps and plans to erase the pencil bridge when the speaker leaves.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"He rejects the speaker's map but signs it anyway so that the speaker will not feel hurt or embarrassed.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He takes over the speaker's map and claims it as his own work, as he always does with shop maps.","is_correct":false,"misconception_token":"misreads-detail"}]$q$::jsonb, $q$He accepts a map that shows the change without erasing his memory, and he treats the speaker as a fellow mapmaker.$q$, $q$Leaving the pencil and signing "beneath mine" shows he approves the compromise and honors the speaker's work. Nothing suggests he plans to erase the pencil; he deliberately "did not touch" it.$q$, 'draft', '6a053eac-0bc2-5347-a207-b0e9e427a623')
