  ('585481c3-1ef3-5cf2-8d31-6487dd613617', null, (select id from public.skills where slug = 'read-g10-character-setting-plot'), null, 'medium',
   $q$Why has Kwame not told anyone that he dislikes the move?$q$, $q$[{"text":"He believes complaining would not change anything, so he puts the family's needs first.","is_correct":true},{"text":"He plans to stay behind with friends and does not want his parents to find out early.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"He is secretly glad to leave and only pretends to dislike the move around his friends.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He has not decided how he feels and is waiting to see the new apartment first.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$He believes complaining would not change anything, so he puts the family's needs first.$q$, $q$The text says, "Saying it would not make the rent any lower," which shows he stays quiet because the move is necessary. He clearly knows his feelings: "He did not like the move."$q$, 'draft', '5d68c5d6-fb15-5827-aaaa-255b58b751af')
