  ('33071b72-a4dd-5380-8fae-414dbae1ab52', null, (select id from public.skills where slug = 'read-g10-character-setting-plot'), null, 'medium',
   $q$Why does Kwame stop arguing with Ama and sit down on her floor?$q$, $q$[{"text":"He realizes he is too tired to argue after packing the kitchen all evening.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"He decides it is his parents' job to deal with Ama when they come home.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Her words, \"I'm not done with it here yet,\" match his own unspoken feeling.","is_correct":true},{"text":"He wants Ama to see that he is angry so she will repack her box quickly.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Her words, "I'm not done with it here yet," match his own unspoken feeling.$q$, $q$He has "nothing to say, because it was exactly the sentence he had been holding in his own chest all week." Tiredness and a wish to show anger are never given as reasons.$q$, 'draft', '5d68c5d6-fb15-5827-aaaa-255b58b751af')
